import React, { useEffect, useState } from 'react';
import { Box, Typography, Stack } from '@mui/material';
import { EmojiObjects, CalendarToday, Person } from '@mui/icons-material';
import MinimalAppBar from '../../Component/MinimalAppBar';
import { useLocation } from 'react-router-dom';
import StatusBadge from '../../Component/StatusBadge';

const DetailRow: React.FC<any> = ({ label, value, icon }) => (
    <Box
        display="flex"
        justifyContent="space-between"
        alignItems="center"
        py={1}
        borderBottom="1px solid #eee"
    >
        <Box display="flex" alignItems="center" gap={1}>
            {icon}
            <Typography fontWeight="bold">{label}</Typography>
        </Box>
        <Typography>{value}</Typography>
    </Box>
);

const LoanDetail: React.FC = () => {

    const location = useLocation();
    const loanData = location.state;
    const [data, setData] = useState<any>(loanData);
    useEffect(() => {
        setData(loanData)
    }, [])
    return (<>
        <MinimalAppBar onBack={() => window.history.back} title="สินเชื่อของฉัน"></MinimalAppBar>
        {data && <Box p={2}>
            <Stack spacing={2}>
                <DetailRow label="เลขที่สัญญา" value={data.id} icon={<EmojiObjects fontSize="small" />} />
                <DetailRow label="สินค้า" value={data.productName} icon={<EmojiObjects fontSize="small" />} />
                <DetailRow label="ยอดทั้งหมด" value={`฿${data.loanAmount.toLocaleString()}`} icon={<EmojiObjects fontSize="small" />} />
                <DetailRow label="จำนวนงวด" value={`฿${data.installmentCount.toLocaleString()}`} icon={<EmojiObjects fontSize="small" />} />
                <DetailRow label="ยอดผ่อน/งวด" value={`฿${data.installmentAmount.toLocaleString()}`} icon={<EmojiObjects fontSize="small" />} />
                <DetailRow label="เริ่มต้น"
                    value={new Date(data.startDate).toLocaleDateString('th-TH', {
                        year: 'numeric',
                        month: 'long',
                        day: 'numeric',
                    })}
                    icon={<CalendarToday fontSize="small" />} />
                <DetailRow label="สิ้นสุด"
                    value={new Date(data.endDate).toLocaleDateString('th-TH', {
                        year: 'numeric',
                        month: 'long',
                        day: 'numeric',
                    })}
                    icon={<CalendarToday fontSize="small" />} />
                <DetailRow label="สถานะ" value={<StatusBadge status={data.status} />} icon={<Person fontSize="small" />} />
            </Stack>
        </Box>}
    </>
    );
};

export default LoanDetail;
